examples:
TypeScript example:

import { generateZod, validateAndInvoke } from '@redwood/sdk-validate'

const schema = generateZod(`function create_order(order_id: string, items: Array<{sku: string, qty: number}>, priority?: string)`);
const payload = { orderId: '123', items: [{ sku: 'SKU-1', qty: '2' }], priority: 'High' }; // note qty as string
const { result, validation_report } = await validateAndInvoke(schema, payload, { coerce: true, idempotency: true });
// validation_report.coerced = ['items[0].qty']

Go example:

// generated struct: CreateOrderRequest
req := generated.CreateOrderRequest{OrderID: "123", Items: []generated.Item{{SKU: "SKU-1", Qty: "2"}}} // Qty as string on purpose
resp, report, err := sdk.ValidateAndInvoke(ctx, "CreateOrder", req, sdk.InvokeOpts{Coerce: true, Idempotency: true})
if err != nil { log.Fatalf("invoke failed: %v", err) }
// report.Coerced -> []string{"Items[0].Qty"}

Streaming resume sketch (TS):
const stream = await validateAndInvoke(streamSchema, payload, { streaming: true, idempotency: true });
for await (const chunk of stream) {
  process(chunk.delta);
  if (networkDrop) {
    // SDK attempts resume automatically; user can subscribe to on_resume_failed to show an error
  }
}
